let fStarC_TypeChecker_Rel_explain (wl : FStarC_TypeChecker_Rel.worklist) (d : FStarC_TypeChecker_Common.prob) (s : (((unit -> string), string) FStar_Pervasives.either ref)) : string =
  (let tmp = (!(FStarC_TypeChecker_Rel.dbg_ExplainRel)) in
  let tmp1 = (if tmp then true else (!(FStarC_TypeChecker_Rel.dbg_Rel))) in
  (if tmp1 then (let tmp2 = (FStarC_Range_Ops.string_of_range (FStarC_TypeChecker_Rel.p_loc d)) in
