    ) in
  let tmp2 = (match d1 with
      | (FStarC_TypeChecker_Common.TProb (tp)) -> (let tmp2 = (FStarC_TypeChecker_Rel.p_env wl d1) in
        let tmp3 = (fStarC_TypeChecker_Normalize_term_to_string tmp2) in
