      | (FStarC_TypeChecker_Common.CProb (cp)) -> (let tmp2 = (FStarC_TypeChecker_Rel.p_env wl d1) in
        let tmp3 = (fStarC_TypeChecker_Normalize_comp_to_string tmp2) in
        (FStarC_TypeChecker_Err.print_discrepancy tmp3 (cp).FStarC_TypeChecker_Common.lhs (cp).FStarC_TypeChecker_Common.rhs))
    ) in
