let fStarC_TypeChecker_Rel_solve_and_commit (wl : FStarC_TypeChecker_Rel.worklist) (err : ((FStarC_TypeChecker_Common.prob * (((unit -> string), string) FStar_Pervasives.either ref)) -> ((((FStarC_TypeChecker_Common.deferred_reason * string * FStarC_TypeChecker_Common.prob)) FStarC_CList.clist * ((FStarC_TypeChecker_Common.deferred_reason * string * FStarC_TypeChecker_Common.prob)) FStarC_CList.clist * (FStarC_TypeChecker_Common.implicit) FStarC_CList.clist)) option)) : ((((FStarC_TypeChecker_Common.deferred_reason * string * FStarC_TypeChecker_Common.prob)) FStarC_CList.clist * ((FStarC_TypeChecker_Common.deferred_reason * string * FStarC_TypeChecker_Common.prob)) FStarC_CList.clist * (FStarC_TypeChecker_Common.implicit) FStarC_CList.clist)) option =
