        | (FStarC_TypeChecker_Rel.Failed (d, s)) -> (let tmp3 = (!(FStarC_TypeChecker_Rel.dbg_ExplainRel)) in
          let tmp4 = (if tmp3 then true else (!(FStarC_TypeChecker_Rel.dbg_Rel))) in
          (if tmp4 then (let tmp5 = (fStarC_TypeChecker_Rel_explain wl d s) in
          (FStarC_Format.print_string tmp5)) else ());
          let result = (err (d, s)) in
